<script setup lang="ts">import { Head, Link, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input';
type Presentation = { id: string; sku: string; name: string; item: string; unit: string; physical_quantity: string; reserved_quantity: string; available_quantity: string; average_unit_cost: number; inventory_value: number; is_below_minimum: boolean; is_package: boolean };
const props = defineProps<{ presentations: { data: Presentation[] }; filters: { search: string }; canAdjust: boolean; canConvertPackages: boolean }>(); const search = ref(props.filters.search); const apply = () => router.get('/inventory', { search: search.value }, { preserveState: true, replace: true }); const money = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 });
</script>
<template><Head title="Inventario" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex flex-col justify-between gap-3 lg:flex-row lg:items-center"><div><h1 class="text-2xl font-semibold">Inventario</h1><p class="text-sm text-muted-foreground">Existencia física, reservada, disponible y costo promedio.</p></div><div class="flex flex-wrap gap-2"><Button variant="outline" as-child><Link href="/inventory/movements">Kardex</Link></Button><Button v-if="canConvertPackages" variant="outline" as-child><Link href="/inventory/packages">Paquetes</Link></Button><Button v-if="canAdjust" as-child><Link href="/inventory/adjustments">Ajustes</Link></Button></div></header><form class="flex max-w-xl gap-2" @submit.prevent="apply"><Input v-model="search" placeholder="Producto, presentación o SKU" /><Button type="submit" variant="outline">Buscar</Button></form><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Presentación</th><th class="px-4 py-3 text-right">Física</th><th class="px-4 py-3 text-right">Reservada</th><th class="px-4 py-3 text-right">Disponible</th><th class="px-4 py-3 text-right">Costo promedio</th><th class="px-4 py-3 text-right">Valor</th></tr></thead><tbody class="divide-y"><tr v-for="presentation in presentations.data" :key="presentation.id" :class="presentation.is_below_minimum && 'bg-amber-50/60 dark:bg-amber-950/20'"><td class="px-4 py-3"><p class="font-medium">{{ presentation.item }} · {{ presentation.name }} <span v-if="presentation.is_package" class="text-xs text-amber-700">Paquete</span></p><code class="text-xs text-muted-foreground">{{ presentation.sku }}</code></td><td class="px-4 py-3 text-right">{{ presentation.physical_quantity }} {{ presentation.unit }}</td><td class="px-4 py-3 text-right">{{ presentation.reserved_quantity }}</td><td class="px-4 py-3 text-right font-medium">{{ presentation.available_quantity }}</td><td class=